_S9_INVARIANTS=(Invariant('EXP-001','product_experience','The local product shell is available before managed-model readiness; setup, download progress, diagnostics and retry are redacted control projections with zero epistemic/execution authority and the browser cannot mark the runtime READY.',"CRITICAL",'tests.test_product_experience_v27'),Invariant('EXP-002','product_experience','The S9 workspace is chat-first with exactly one ACTIVE semantic viewport containing the existing sealed HSPv2 frame; inspector, orbit rail, command palette, artifacts, diagnostics and traditional controls are progressively disclosed zero-authority chrome and cannot create a parallel semantic channel or browser-to-model path.',"CRITICAL",'tests.test_product_experience_v27'),Invariant('EXP-003','product_experience','Voice input is local/on-device or loopback, bound to the current S8 writer when brokered by iKant, never auto-submits and cannot approve authority; voice output is optional local-service rendering only after exact ACK of the same sealed TURN Surface A and never becomes a second semantic message.',"CRITICAL",'tests.test_product_experience_v27'),Invariant('EXP-004','product_experience','The canonical product path preserves T&C -> PROBE -> INITIALIZE, S8 single-writer recovery/idempotence, keyboard access, responsive/reduced-motion behavior and explicit degraded/setup recovery while progressive disclosure never collapses presentation, readiness, diagnostics or convenience into authority.',"CRITICAL",'tests.test_product_experience_v27'),)
